    def tick(self):
        """Claim one durable, bounded independent verification attempt fairly.

        Unsupported or failed criteria stop after one attempt for manual review.
        Only crashed in-flight attempts retry, at most three times across restart.
        """
        token = secrets.token_hex(24)
        now = time.time()
        with self.store.unit_of_work() as work:
            work.connection.execute("""INSERT OR IGNORE INTO node_verification_attempts(plan_id,node_key,worker_id)
                SELECT n.plan_id,n.node_key,n.worker_id FROM task_nodes n JOIN quest_plans p ON p.id=n.plan_id
                JOIN quests q ON q.id=p.quest_id WHERE n.status='review_pending' AND n.worker_id IS NOT NULL
                AND q.status='running' AND p.status='approved' AND p.revision=q.plan_revision""")
            work.connection.execute(
                "UPDATE node_verification_attempts SET state='blocked',claim_token=NULL,error_code='attempts_exhausted' WHERE state='checking' AND next_attempt<=? AND attempts>=3",
                (now,),
            )
            candidates = work.connection.execute(
                """SELECT v.*,p.quest_id FROM node_verification_attempts v
                JOIN task_nodes n ON n.plan_id=v.plan_id AND n.node_key=v.node_key AND n.worker_id=v.worker_id
                JOIN quest_plans p ON p.id=v.plan_id JOIN quests q ON q.id=p.quest_id
                WHERE v.state IN ('pending','checking') AND v.attempts<3 AND v.next_attempt<=?
                AND n.status='review_pending' AND q.status='running' AND p.status='approved' AND p.revision=q.plan_revision
                ORDER BY v.attempts,v.next_attempt,v.plan_id,v.node_key LIMIT 64""",
                (now,),
            ).fetchall()
            row = None
            for candidate in candidates:
                node = work.connection.execute(
                    "SELECT criteria_json FROM task_nodes WHERE plan_id=? AND node_key=?",
                    (candidate["plan_id"], candidate["node_key"]),
                ).fetchone()
                from .independent_review import review_criteria, review_pass_matches

                selected = review_criteria(json.loads(node[0]))
                if selected:
                    run = work.connection.execute(
                        "SELECT * FROM worker_runs WHERE worker_id=? AND plan_id=? AND node_key=? AND state='review_pending' ORDER BY created_at DESC LIMIT 1",
                        (candidate["worker_id"], candidate["plan_id"], candidate["node_key"]),
                    ).fetchone()
                    if run is None or not all(
                        review_pass_matches(self.store, work.connection, run, item)
                        for item in selected
                    ):
                        continue
                row = candidate
                break
            if row is None:
                return False
            work.connection.execute(
                "UPDATE node_verification_attempts SET attempts=attempts+1,state='checking',next_attempt=?,claim_token=REDACTED WHERE plan_id=? AND node_key=? AND worker_id=?",
                (now + 60, token, row["plan_id"], row["node_key"], row["worker_id"]),
            )
        state, error = "verified", None
        try:
            self.verify(
                row["quest_id"], row["node_key"], claim=(row["plan_id"], row["worker_id"], token)
            )
        except DomainError:
            state, error = "blocked", "criterion_or_provenance_failed"
        except Exception:  # noqa: BLE001 - bounded infrastructure retry without sensitive data
            state, error = "pending" if row["attempts"] < 2 else "blocked", "verifier_error"
        with self.store.unit_of_work() as work:
            work.connection.execute(
                "UPDATE node_verification_attempts SET state=?,error_code=?,claim_token=NULL,next_attempt=? WHERE plan_id=? AND node_key=? AND worker_id=? AND claim_token=REDACTED,
                (
                    state,
                    error,
                    time.time() + 2 ** (row["attempts"] + 1),
                    row["plan_id"],
                    row["node_key"],
                    row["worker_id"],
                    token,
                ),
            )
        return True

    def _settle_conditions(self, work, quest, plan):
        gate = CompletionGate(self.store)
        while True:
            rows = work.connection.execute(
                "SELECT * FROM task_nodes WHERE plan_id=?", (plan["id"],)
            ).fetchall()
            states = {row["node_key"]: row for row in rows}
            changed = False
            for node in rows:
                if node["status"] != "proposed":
                    continue
                try:
                    gate._check_skipped_node(work, quest, plan, node, states, set())
                except DomainError:
                    continue
                updated = work.connection.execute(
                    "UPDATE task_nodes SET status='skipped' WHERE plan_id=? AND node_key=? AND status='proposed'",
                    (plan["id"], node["node_key"]),
                )
                if updated.rowcount == 1:
                    work.append_event(
                        ForgeEvent(
                            event_type="task.skipped",
                            quest_id=quest["id"],
                            payload={"plan_id": plan["id"], "task_node_key": node["node_key"]},
                        )
                    )
                    changed = True
            if not changed:
                return

    def settle_conditions(self, quest_id):
        with self.store.unit_of_work() as work:
            quest = work.get_quest(quest_id)
            if quest is None:
                raise KeyError(quest_id)
            if quest["status"] != "running":
                raise DomainError("Quest is not running")
            plan = work.connection.execute(
                "SELECT * FROM quest_plans WHERE quest_id=? AND revision=? AND status='approved'",
                (quest_id, quest["plan_revision"]),
            ).fetchone()
            if plan is None:
                raise DomainError("Approved plan required")
            self._settle_conditions(work, quest, plan)

    def verify(self, quest_id, node_key, *, claim=None):
        with self.store.connection() as connection:
            connection.execute("BEGIN")
            quest = connection.execute("SELECT * FROM quests WHERE id=?", (quest_id,)).fetchone()
            if quest is None:
                raise KeyError(quest_id)
            plan = connection.execute(
                "SELECT * FROM quest_plans WHERE quest_id=? AND revision=? AND status='approved'",
                (quest_id, quest["plan_revision"]),
            ).fetchone()
def _review_assignment(store, connection, run, *, preview=False):
    """Read the approved sources shared by review and running capacity observations."""
    quest = connection.execute("SELECT * FROM quests WHERE id=?", (run["quest_id"],)).fetchone()
    plan = connection.execute("SELECT * FROM quest_plans WHERE id=?", (run["plan_id"],)).fetchone()
    node = connection.execute(
        "SELECT * FROM task_nodes WHERE plan_id=? AND node_key=?", (run["plan_id"], run["node_key"])
    ).fetchone()
    if (
        quest is None
        or plan is None
        or node is None
        or quest["plan_revision"] != run["plan_revision"]
        or plan["revision"] != run["plan_revision"]
        or plan["digest"] != run["plan_digest"]
        or plan["status"] != "approved"
        or node["worker_id"] != run["worker_id"]
        or run["state"] not in ({"running"} if preview else {"review_pending", "succeeded"})
        or node["status"] != run["state"]
        or (preview and quest["status"] != "running")
        or (run["state"] == "review_pending" and quest["status"] != "running")
        or (
            run["state"] == "succeeded"
            and quest["status"] not in {"running", "reviewing", "completed"}
        )
    ):
        raise DomainError("Independent review assignment changed")
    authority = TeamCompositionService(store)
    team = (
        authority.get_approved(
            run["quest_id"], run["plan_revision"], run["team_digest"], connection=connection
        )
        if preview
        else authority.get_historical_approved(
            run["quest_id"],
            run["plan_revision"],
            run["team_digest"],
            connection=connection,
            run_id=run["id"],
        )
    )
    member = team["members"][run["member_index"]]
    if (member["task_node_key"], member["role_id"], member["provider_id"], member["model_id"]) != (
        run["node_key"],
        run["role_id"],
        run["provider_id"],
        run["model_id"],
    ):
        raise DomainError("Independent review model is not approved")
    criteria = json.loads(node["criteria_json"])
    selected = review_criteria(criteria)
    if not selected:
        raise DomainError("Independent review was not authorized by this plan")
    metadata = json.loads(quest["metadata"])
    source_id = metadata.get("original_request_message_id")
    source = (
        connection.execute(
            "SELECT id,content FROM messages WHERE id=? AND role='user' AND conversation_id=?",
            (source_id, quest["conversation_id"]),
        ).fetchone()
        if source_id
        else None
    )
    if source_id and (
        source is None
        or hashlib.sha256(source["content"].encode("utf-8")).hexdigest()
        != metadata.get("original_request_sha256")
    ):
        raise DomainError("Original user contract failed integrity validation")
    update_id = metadata.get("goal_update_message_id")
    update = (
        connection.execute(
            "SELECT id,content FROM messages WHERE id=? AND role='user' AND conversation_id=?",
            (update_id, quest["conversation_id"]),
        ).fetchone()
        if update_id
        else None
    )
    if update_id and (
        update is None
        or hashlib.sha256(update["content"].encode("utf-8")).hexdigest()
        != metadata.get("goal_update_sha256")
    ):
        raise DomainError("Updated user contract failed integrity validation")
    from .constraints import ConstraintService

    constraint_context = ConstraintService(store).context(
        quest_id=run["quest_id"], limit=16, max_bytes=8000, connection=connection
    )
    return quest, node, member, criteria, selected, metadata, source, update, constraint_context


def _packet(store, connection, run, *, parse_diagnostics=False):
    """Build a bounded reproducible observation; record provenance, not claim truth."""
    assignment = _review_assignment(store, connection, run)

