def validate_plan_contract(store, connection, quest_id, graph, *, preserved_completed_keys=()):
    binding = graph.get("execution_constraints")
    limits = validate_execution_constraints(connection, quest_id, binding)
    if len(graph["nodes"]) > limits.get("max_nodes", 128) or graph["max_total_tokens"] > limits.get(
        "max_total_tokens", 1000000
    ):
        raise DomainError("Plan exceeds source-bound task execution limits")
    if graph.get("max_duration_seconds") and graph["max_duration_seconds"] > limits.get(
        "max_duration_seconds", 1000000000
    ):
        raise DomainError("Plan duration exceeds source-bound task limit")
    contract = graph.get("capacity_contract")
    if contract is None:
        return
    if contract.get("version") != VERSION:
        raise DomainError("Unknown plan capacity contract")
    if not isinstance(contract.get("input_inventory"), list) or not isinstance(
        contract.get("nodes"), dict
    ):
        raise DomainError("Capacity contract requires verified inventory and per-node envelopes")
    verify_input_inventory(store, contract["input_inventory"])
    known = {item["path"] for item in contract["input_inventory"]}
    preserved = set(contract.get("preserved_completed_keys", []))
    proved_completed = {
        item["node_key"] for item in graph.get("revision_lineage", {}).get("completed_nodes", [])
    }
    if preserved - proved_completed - set(preserved_completed_keys):
        raise DomainError("Preserved capacity nodes require verified completed execution lineage")
    if preserved and not preserved.issubset({node["key"] for node in graph["nodes"]}):
        raise DomainError("Unknown preserved completed capacity node")
    for node in graph["nodes"]:
        if node["key"] in preserved:
            continue
        if node.get("required_input_paths") is None or not node.get("capacity_bounds"):
            raise DomainError("New capacity contract requires explicit node paths and byte bounds")
        parents = {edge["source"] for edge in graph["edges"] if edge["target"] == node["key"]}
        delivery_parents = {
            edge["source"]
            for edge in graph["edges"]
            if edge["target"] == node["key"] and edge["condition"] == "success"
        }
        deliveries = node.get("required_predecessor_deliveries") or []
        if deliveries and (
            len(deliveries) > 8
            or len(deliveries) != len(set(deliveries))
            or set(deliveries) - delivery_parents
            or "worker_read_completed_delivery" not in node["allowed_tools"]
        ):
            raise DomainError("Completed delivery requires declared direct success predecessors")
        future = {
            other.get("expected_artifact") for other in graph["nodes"] if other["key"] in parents
        }
        if set(node["required_input_paths"]) - known - future:
            raise DomainError("Required input has no verified source or bounded predecessor")
    reserve = graph.get("coordination_reserve_tokens")
    if (
        not reserve
        or sum(node["budget_tokens"] for node in graph["nodes"]) + reserve
        > graph["max_total_tokens"]
    ):
        raise DomainError("Plan must retain its explicit coordination reserve")
"""Explicit new review contracts; legacy packets never acquire these bounds."""

import json

from .domain import DomainError

REVIEW_ENVELOPE_VERSION = "review-envelope-v1"
_FIELDS = {
    "version",
    "max_source_bytes",
    "max_artifact_bytes",
    "max_delivery_bytes",
    "max_review_input_tokens",
    "verdict_tokens",
    "correction_input_tokens",
    "correction_output_tokens",
    "correction_calls",
}


class ReviewEnvelopeError(DomainError):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _json(value):
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    )


def validate_review_envelope(value):
    """Return a copy of a fully explicit approved policy, without adding defaults."""
    if not isinstance(value, dict) or set(value) != _FIELDS:
        raise ReviewEnvelopeError("review_envelope_fields_invalid")
    if value["version"] != REVIEW_ENVELOPE_VERSION:
        raise ReviewEnvelopeError("review_envelope_version_invalid")
    for key in _FIELDS - {"version"}:
        if type(value[key]) is not int or value[key] < (
            0 if key in {"max_source_bytes", "max_artifact_bytes"} else 1
        ):
            raise ReviewEnvelopeError("review_envelope_bounds_invalid")
    if (
        any(
            value[key] > 65536
            for key in (
                "max_source_bytes",
                "max_artifact_bytes",
                "max_delivery_bytes",
                "max_review_input_tokens",
                "correction_input_tokens",
            )
        )
        or not 1024 <= value["verdict_tokens"] <= 8192
        or value["correction_output_tokens"] > 8192
        or value["correction_calls"] not in {1, 2}
        or sum(
            value[key] for key in ("max_source_bytes", "max_artifact_bytes", "max_delivery_bytes")
        )
        >= 65536
    ):
        raise ReviewEnvelopeError("review_envelope_bounds_invalid")
    return dict(value)


def review_cycle_reserve(envelope, *, reviews_remaining=2, correction_calls_remaining=None):
    """Policy reserve for two reviews and one correction, within existing limits.

    Runtime callers pass the remaining stages after settled reviews/revision;
    this never charges, refunds or restores any previously consumed allowance.
    """
    envelope = validate_review_envelope(envelope)
    calls = (
        envelope["correction_calls"]
        if correction_calls_remaining is None
        else correction_calls_remaining
    )
    if (
        type(reviews_remaining) is not int
        or not 0 <= reviews_remaining <= 2
        or type(calls) is not int
        or not 0 <= calls <= envelope["correction_calls"]
    ):
        raise ReviewEnvelopeError("review_cycle_stage_invalid")
    return reviews_remaining * (
        envelope["max_review_input_tokens"] + envelope["verdict_tokens"]
    ) + calls * (envelope["correction_input_tokens"] + envelope["correction_output_tokens"])


def review_cycle_state(connection, run_id, envelope):
    """Read remaining stages from durable starts and applied model-review revision.

    Refunded unsent reviews/corrections do not consume a stage. Unknown admitted
    calls retain their charge and consume a stage; no unknown usage is zeroed.
    """
    envelope = validate_review_envelope(envelope)
    starts = connection.execute(
        "SELECT payload FROM events e WHERE e.event_type='review.started' "
        "AND json_extract(e.payload,'$.run_id')=? AND NOT EXISTS("
